from __future__ import absolute_import, division
from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger
from taf.ul.trs_e2e_fw.lib.oam.admin.admin_factory import AdminBaseClass

logger = BackgroundLogger.Instance()


class MassDiagnostics(AdminBaseClass):
    """Cell Operations"""

    def __init__(self):
        super(MassDiagnostics, self).__init__()

    def run_customized_check(self, **kwargs):
        system_module_checkpoints_ids = kwargs['system_module_checkpoints_ids']
        radio_modules = kwargs['radio_modules']
        timeout = kwargs.pop('timeout', 60)
        alias = kwargs.pop('alias', 'default')
        detailed_output = kwargs.pop('detailed_output:', False)

        return self.factory.admin.run_customized_check(system_module_checkpoints_ids, radio_modules,
                                                       detailed_output=detailed_output, timeout=timeout,
                                                       connection=alias)

    def fetch_diagnostic_checkpoints(self, **kwargs):
        detailed_output = kwargs.pop('detailed_output:', False)
        timeout = kwargs.pop('timeout', 60)
        alias = kwargs.pop('alias', 'default')

        return self.factory.admin.fetch_diagnostic_checkpoints(detailed_output=detailed_output, timeout=timeout,
                                                               connection=alias)

    def run_diagnostic_check(self, **kwargs):
        allow_service_impact = kwargs.get('allow_service_impact', False)
        timeout = kwargs.pop('timeout', 60)
        alias = kwargs.pop('alias', 'default')
        detailed_output = kwargs.pop('detailed_output:', False)

        return self.factory.admin.run_diagnostic_check(allow_service_impact, detailed_output=detailed_output,
                                                       timeout=timeout, connection=alias)

    def get_diagnostic_report(self, **kwargs):
        detailed_output = kwargs.pop('detailed_output:', False)
        timeout = kwargs.pop('timeout', 60)
        alias = kwargs.pop('alias', 'default')

        return self.factory.admin.get_diagnostic_report(detailed_output=detailed_output, timeout=timeout,
                                                        connection=alias)

    def configure_cplane_traces(self, **kwargs):
        dscp = kwargs.get("dscp")
        alias = kwargs.pop('alias', 'default')
        timeout = kwargs.pop('timeout', 60)
        detailed_output = kwargs.pop('detailed_output:', False)
        return self.factory.admin.configure_cplane_traces(dscp=int(dscp), timeout=timeout, detailed_output=detailed_output, connection=alias)